<div class="page-header"><div><h2>Oficinas</h2><p>Gerencie oficinas, orientadores responsáveis, alunos e produção.</p></div><?php if(is_professor()): ?><a href="<?= e(url('/oficinas/criar')) ?>" class="btn btn-primary">Nova Oficina</a><?php endif; ?></div>
<?php if($workshops): ?><div class="grid three"><?php foreach($workshops as $w): ?><section class="card workshop-card"><div class="workshop-thumb-wrap"><?php if(!empty($w['image_path'])): ?><img class="workshop-thumb" src="<?= e(url($w['image_path'])) ?>" alt="<?= e($w['name']) ?>"><?php else: ?><div class="workshop-thumb fallback" style="background:<?= e($w['color']??'#4f46e5') ?>">GA</div><?php endif; ?></div><h3><?= e($w['name']) ?></h3><p><?= e($w['description']) ?></p><div class="metric-line"><span>Responsável</span><strong><?= e($w['responsible_name']??'Não definido') ?></strong></div><div class="metric-line"><span>Alunos</span><strong><?= e($w['participants_count']??0) ?></strong></div><div class="metric-line"><span>Total produzido</span><strong><?= e($w['total_production']??0) ?></strong></div><div class="actions"><a href="<?= e(url('/oficinas/'.$w['id'])) ?>" class="btn btn-secondary">Ver detalhes</a><?php if(is_professor()): ?><a href="<?= e(url('/oficinas/'.$w['id'].'/editar')) ?>" class="btn btn-secondary">Editar</a><?php endif; ?></div></section><?php endforeach; ?></div><?php else: ?><section class="panel"><div class="panel-body empty">Nenhuma oficina cadastrada.</div></section><?php endif; ?>
